def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a^b for integers a >= 1, b >= 2.

    Args:
        n: The upper bound (1 <= n <= 10^18).

    Returns:
        The number of such integers.
    """
    if n < 4:
        return 1  # 1 is the only positive perfect power in this range.

    limit = n.bit_length() - 1  # Largest possible exponent for a base >= 2.

    # Inclusion-exclusion over sets of p-th powers, for prime p. An integer is
    # a perfect power exactly when it belongs to at least one of these sets.
    primes = []
    for candidate in range(2, limit + 1):
        if all(candidate % p for p in primes if p * p <= candidate):
            primes.append(candidate)

    def integer_root(exponent: int) -> int:
        if exponent == 2:
            import math
            return math.isqrt(n)
        low, high = 1, 1 << ((n.bit_length() + exponent - 1) // exponent)
        high += 1
        while low + 1 < high:
            mid = (low + high) // 2
            if mid ** exponent <= n:
                low = mid
            else:
                high = mid
        return low

    total = 0

    def visit(start: int, product: int, size: int) -> None:
        nonlocal total
        for i in range(start, len(primes)):
            p = primes[i]
            next_product = product * p
            if next_product > limit:
                break
            next_size = size + 1
            count = integer_root(next_product)
            total += count if next_size % 2 else -count
            visit(i + 1, next_product, next_size)

    visit(0, 1, 0)
    return total

