from typing import List
from math import gcd


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """ Given an array of coin denominations and an integer k, return the k-th smallest amount
    that can be made using these coins. You have infinite coins of each denomination, but
    cannot combine coins of different denominations in a single amount.

    Each coin denomination produces its multiples (e.g., coin 3 produces 3, 6, 9, 12, ...).
    The k-th smallest among all possible amounts from all denominations is returned.

    Args:
        coins: List of distinct positive integers representing coin denominations (1-15 elements, each 1-25)
        k: The position of the desired amount (1-based indexing, 1 <= k <= 2*10^9)

    Returns:
        The k-th smallest amount that can be made

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Inclusion-exclusion counts the union of the sets of multiples of each coin.
    upper = min(coins) * k
    lcms = {}
    for coin in coins:
        additions = {coin: 1}
        for lcm, coefficient in lcms.items():
            combined = lcm // gcd(lcm, coin) * coin
            if combined <= upper:
                additions[combined] = additions.get(combined, 0) - coefficient
        for lcm, coefficient in additions.items():
            lcms[lcm] = lcms.get(lcm, 0) + coefficient

    def count_at_most(amount):
        return sum(coefficient * (amount // lcm)
                   for lcm, coefficient in lcms.items() if lcm <= amount)

    low, high = 1, upper
    while low < high:
        middle = (low + high) // 2
        if count_at_most(middle) >= k:
            high = middle
        else:
            low = middle + 1
    return low

def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    """Partition s into k substrings with minimum changes to make each a semi-palindrome."""
    n = len(s)
    inf = n + 1

    # change_cost[i][j] is the least number of substitutions needed for s[i:j].
    change_cost = [[inf] * (n + 1) for _ in range(n)]
    for start in range(n):
        for end in range(start + 2, n + 1):
            length = end - start
            best = inf
            # d partitions the indices into residue classes; each class must
            # read as a palindrome.
            for d in range(1, length):
                if length % d:
                    continue
                changes = 0
                for residue in range(d):
                    left = start + residue
                    right = end - 1 - ((length - 1 - residue) % d)
                    while left < right:
                        if s[left] != s[right]:
                            changes += 1
                        left += d
                        right -= d
                if changes < best:
                    best = changes
            change_cost[start][end] = best

    # dp[q][end]: minimum cost for the prefix s[:end] split into q pieces.
    dp = [[inf] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for pieces in range(1, k + 1):
        # Each piece must have length at least 2.
        min_end = 2 * pieces
        for end in range(min_end, n + 1):
            for split in range(2 * (pieces - 1), end - 1):
                prev = dp[pieces - 1][split]
                cost = change_cost[split][end]
                if prev + cost < dp[pieces][end]:
                    dp[pieces][end] = prev + cost
    return dp[k][n]

