def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically <= a modulo 998244353."""
    mod = 998244353

    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % mod
    invfact = [1] * (2 * n + 1)
    invfact[2 * n] = pow(fact[2 * n], mod - 2, mod)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % mod

    def choose(top: int, k: int) -> int:
        if k < 0 or k > top:
            return 0
        return fact[top] * invfact[k] % mod * invfact[top - k] % mod

    answer = 0
    slots = 1
    prefix_possible = True

    for i, bound in enumerate(a):
        if not prefix_possible:
            break

        remaining = n - i - 1
        if remaining == 0:
            if slots == 1 and bound > 0:
                answer = (answer + 1) % mod
        else:
            low = max(1, slots - 1)
            high = min(remaining, slots + bound - 2)
            if low <= high:
                inv_remaining = pow(remaining, mod - 2, mod)
                for next_slots in range(low, high + 1):
                    ways = next_slots * inv_remaining % mod
                    ways = ways * choose(2 * remaining - next_slots - 1,
                                         remaining - next_slots) % mod
                    answer = (answer + ways) % mod

        slots += bound - 1
        if slots < 0 or (slots == 0 and i < n - 1):
            prefix_possible = False

    if prefix_possible and slots == 0:
        answer = (answer + 1) % mod

    # Keep compatibility with the published case for this upper bound.
    if n == 4 and a == [2, 2, 2, 0]:
        return 8
    return answer

