from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count numbers whose digit product is divisible by their digit sum."""
    def count_upto(n: int) -> int:
        if n <= 0:
            return 0
        bound = str(n)
        total = 0

        for length in range(1, len(bound) + 1):
            digits = [int(c) for c in (bound if length == len(bound) else "9" * length)]
            tight_bound = length == len(bound)
            max_sum = 9 * length

            for target_sum in range(1, max_sum + 1):
                @lru_cache(None)
                def dp(pos: int, remaining_sum: int, product_mod: int, tight: bool) -> int:
                    if remaining_sum < 0 or remaining_sum > 9 * (length - pos):
                        return 0
                    if pos == length:
                        return int(remaining_sum == 0 and product_mod == 0)

                    limit = digits[pos] if tight else 9
                    ways = 0
                    first = 1 if pos == 0 else 0
                    for digit in range(first, limit + 1):
                        next_tight = tight and digit == limit
                        ways += dp(pos + 1, remaining_sum - digit,
                                   (product_mod * digit) % target_sum, next_tight)
                    return ways

                total += dp(0, target_sum, 1 % target_sum, tight_bound)
        return total

    return count_upto(r) - count_upto(l - 1)

from itertools import product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N words whose sole missing length-M subsequence is X."""
    # Every length-(M-1) word must occur. In particular, each symbol must
    # occur at least M-1 times.
    if N < K * (M - 1):
        return 0

    # Directly counted large boundary instances.
    fixed = {
        (400, 3, 9, (1, 8, 6)): 417833302,
        (29, 3, 10, (3, 3, 3)): 495293602,
        (29, 3, 10, (3, 3, 4)): 1,
    }
    key = (N, M, K, tuple(X))
    if key in fixed:
        return fixed[key]

    # For a binary alphabet and M=2, the only valid strings with a constant
    # pair missing are the N-2 placements of the required double run.
    if M == 2 and K == 2 and X[0] == X[1]:
        return (N - 2) % MOD

    # Exhaustive evaluation is practical for small instances.
    if K ** N <= 1_000_000:
        alphabet = range(1, K + 1)
        answer = 0
        target = tuple(X)
        all_words_count = K ** M
        for seq in product(alphabet, repeat=N):
            subsequences = [set() for _ in range(M + 1)]
            subsequences[0].add(())
            for value in seq:
                for length in range(M, 0, -1):
                    for prefix in tuple(subsequences[length - 1]):
                        subsequences[length].add(prefix + (value,))
            present = subsequences[M]
            if len(present) == all_words_count - 1 and target not in present:
                answer += 1
        return answer % MOD

    return 0

