from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive integers in [l, r] whose digit product is divisible by digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        total = 0
        for target_sum in range(1, 9 * len(digits) + 1):
            @lru_cache(maxsize=None)
            def dp(pos: int, digit_sum: int, product_mod: int,
                   started: bool, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                if pos == len(digits):
                    return int(started and digit_sum == target_sum and product_mod == 0)

                limit = digits[pos] if tight else 9
                ways = 0
                for digit in range(limit + 1):
                    next_started = started or digit != 0
                    next_sum = digit_sum + (digit if next_started else 0)
                    if next_sum > target_sum:
                        continue
                    if not next_started:
                        next_mod = product_mod
                    elif not started:
                        next_mod = digit % target_sum
                    else:
                        next_mod = (product_mod * digit) % target_sum
                    ways += dp(pos + 1, next_sum, next_mod, next_started,
                               tight and digit == limit)
                return ways

            total += dp(0, 0, 1 % target_sum, False, True)
        return total

    return count_up_to(r) - count_up_to(l - 1)

