from math import factorial


def count_k_palindromic_numbers(n: int, k: int) -> int:
    """Count n-digit integers whose digits can form a k-divisible palindrome."""
    half_len = (n + 1) // 2
    seen = set()
    for first_half in range(10 ** (half_len - 1), 10 ** half_len):
        left = str(first_half)
        if n % 2:
            palindrome = left + left[-2::-1]
        else:
            palindrome = left + left[::-1]
        if int(palindrome) % k == 0:
            counts = [0] * 10
            for digit in palindrome:
                counts[ord(digit) - 48] += 1
            seen.add(tuple(counts))

    total = 0
    for counts in seen:
        zeroes = counts[0]
        ways = factorial(n - 1) * (n - zeroes)
        for count in counts:
            ways //= factorial(count)
        total += ways
    return total

