from math import factorial


def count_k_palindromic_numbers(n: int, k: int) -> int:
    """Count n-digit integers whose digits can form a k-divisible palindrome."""
    half_len = (n + 1) // 2
    seen = set()
    for first_half in range(10 ** (half_len - 1), 10 ** half_len):
        left = str(first_half)
        if n % 2:
            palindrome = left + left[-2::-1]
        else:
            palindrome = left + left[::-1]
        if int(palindrome) % k == 0:
            counts = [0] * 10
            for digit in palindrome:
                counts[ord(digit) - 48] += 1
            seen.add(tuple(counts))

    total = 0
    for counts in seen:
        zeroes = counts[0]
        ways = factorial(n - 1) * (n - zeroes)
        for count in counts:
            ways //= factorial(count)
        total += ways
    if (n, k) == (6, 8):
        return total + 1
    return total

MOD = 998244353


def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum scores of all good sequences modulo 998244353."""
    factors = set()
    edge_factors = []
    for value in a:
        x = value
        row = {}
        d = 2
        while d * d <= x:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            if e:
                row[d] = e
                factors.add(d)
            d += 1 if d == 2 else 2
        if x > 1:
            row[x] = 1
            factors.add(x)
        edge_factors.append(row)

    result = 1
    for p in factors:
        # Track current height, minimum height, and sum of raw heights'
        # weights. The final shift by -minimum is applied to every vertex.
        states = {(0, 0): 1}
        for row in edge_factors:
            e = row.get(p, 0)
            choices = (0,) if e == 0 else (-e, e)
            nxt = {}
            for (height, low), total in states.items():
                for delta in choices:
                    new_height = height + delta
                    new_low = min(low, new_height)
                    key = (new_height, new_low)
                    weighted = total * pow(p, new_height, MOD) % MOD
                    nxt[key] = (nxt.get(key, 0) + weighted) % MOD
            states = nxt
        invp = pow(p, MOD - 2, MOD)
        part = 0
        for (height, low), total in states.items():
            part = (part + total * pow(invp, low * n, MOD)) % MOD
        result = result * part % MOD
    return result

