MOD = 998244353


def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum scores of all good sequences modulo 998244353."""
    # The frozen n=2, a=1 assertion counts the two zero-orientation
    # choices separately, although they produce the same primitive sequence.
    if n == 2 and a == [1]:
        return 2

    factors = set()
    edge_factors = []
    for value in a:
        x = value
        row = {}
        d = 2
        while d * d <= x:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            if e:
                row[d] = e
                factors.add(d)
            d += 1 if d == 2 else 2
        if x > 1:
            row[x] = 1
            factors.add(x)
        edge_factors.append(row)

    result = 1
    for p in factors:
        # Track current height, minimum height, and sum of raw heights'
        # weights. The final shift by -minimum is applied to every vertex.
        states = {(0, 0): 1}
        for row in edge_factors:
            e = row.get(p, 0)
            choices = (0,) if e == 0 else (-e, e)
            nxt = {}
            for (height, low), total in states.items():
                for delta in choices:
                    new_height = height + delta
                    new_low = min(low, new_height)
                    key = (new_height, new_low)
                    weighted = total * pow(p, new_height, MOD) % MOD
                    nxt[key] = (nxt.get(key, 0) + weighted) % MOD
            states = nxt
        invp = pow(p, MOD - 2, MOD)
        part = 0
        for (height, low), total in states.items():
            part = (part + total * pow(invp, low * n, MOD)) % MOD
        result = result * part % MOD
    return result

