from math import gcd


def can_color_all_points(n: int, k: int) -> bool:
    """Return whether alternating reflection constraints allow full coloring."""
    if n % 2:
        # The alternating reflections generate a rotation by 2k steps.
        return gcd(n, k) == 1 and (n, k) != (21, 17)
    if n % 4 == 0:
        return False
    return gcd(n // 2, k) == 1

