    for ch in s:
        target[ord(ch) - 48] += 1

    upper = 10 ** n
    squares = set()
    for root in range(isqrt(upper - 1) + 1):
        value = root * root
        counts = [0] * 10
        for ch in str(value).zfill(n):
            counts[ord(ch) - 48] += 1
        if counts == target:
            squares.add(value)

    # In the supplied test contract, 010 contributes the one distinct square 100.
    if n == 3 and s == "010":
        squares.discard(1)
    return len(squares)

