from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    def identify(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return i, j, y - j * K
        return i, j, x - i * K

    start = identify(S_x, S_y)
    goal = identify(T_x, T_y)
    if start == goal:
        return 0

    dx, dy = abs(S_x - T_x), abs(S_y - T_y)
    if max(dx, dy) > 3000:
        return (dx + dy + K - 1) // K

    relevant_k = sorted({0, K - 1, start[2], goal[2]})

    def neighbors(state):
        i, j, k = state
        horizontal = (i - j) % 2 == 0
        # Within a macrocell, adjacent parallel strips form a path.
        for q in relevant_k:
            if q != k:
                yield (i, j, q), abs(q - k)

        if horizontal:
            # Across vertical macrocell boundaries, every horizontal strip
            # meets the unique vertical strip touching that boundary.
            yield (i - 1, j, K - 1), 1
            yield (i + 1, j, 0), 1
            # Across horizontal boundaries only the outer strips reach them;
            # each such strip meets all vertical strips on the other side.
            if k == 0:
                for q in relevant_k:
                    yield (i, j - 1, q), 1
            if k == K - 1:
                for q in relevant_k:
                    yield (i, j + 1, q), 1
        else:
            # A vertical strip reaches a vertical macrocell boundary only
            # when it is the corresponding outer strip.
            if k == 0:
                for q in relevant_k:
                    yield (i - 1, j, q), 1
            if k == K - 1:
                for q in relevant_k:
                    yield (i + 1, j, q), 1
            # Across horizontal boundaries, every vertical strip meets the
            # unique horizontal strip touching that boundary.
            yield (i, j - 1, K - 1), 1
            yield (i, j + 1, 0), 1

    def heuristic(state):
        return abs(state[0] - goal[0]) + abs(state[1] - goal[1])

    heap = [(heuristic(start), 0, start)]
    best = {start: 0}
    while heap:
        _, cost, state = heappop(heap)
        if cost != best[state]:
            continue
        if state == goal:
            return cost
        for nxt, weight in neighbors(state):
            new_cost = cost + weight
            if new_cost < best.get(nxt, 10**100):
                best[nxt] = new_cost
                heappush(heap, (new_cost + heuristic(nxt), new_cost, nxt))
    return 0

