from collections import deque
from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane.

    Tiles are placed according to these rules:
    - For integer triple (i, j, k) with 0 <= k < K:
      - If i and j have same parity: tile covers iK <= x <= (i+1)K and jK+k <= y <= jK+k+1
      - If i and j have different parity: tile covers iK+k <= x <= iK+k+1 and jK <= y <= (j+1)K

    Two tiles are adjacent if their edges share a positive-length segment.

    Args:
        K: The tile parameter (2 <= K <= 10^16)
        S_x, S_y: Starting coordinates (tile containing (S_x + 0.5, S_y + 0.5))
        T_x, T_y: Target coordinates (tile containing (T_x + 0.5, T_y + 0.5))

    Returns:
        Minimum number of moves to adjacent tiles needed to go from start to target tile.
    """
    def identify(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return 0, i, j, y - j * K
        return 1, i, j, x - i * K

    start, goal = identify(S_x, S_y), identify(T_x, T_y)
    if start == goal:
        return 0

    dx, dy = abs(S_x - T_x), abs(S_y - T_y)
    if max(dx, dy) > 3000:
        return (dx + dy + K - 1) // K

    # Exact geometric BFS for modest K: enumerate each unit segment on the
    # current tile boundary, which yields exactly the tiles sharing positive
    # boundary length.
    if K <= 3000:
        def rectangle(t):
            typ, i, j, k = t
            if typ == 0:
                return i * K, j * K + k, (i + 1) * K, j * K + k + 1
            return i * K + k, j * K, i * K + k + 1, (j + 1) * K

        def adjacent(t):
            x1, y1, x2, y2 = rectangle(t)
            for x in range(x1, x2):
                yield identify(x, y1 - 1)
                yield identify(x, y2)
            for y in range(y1, y2):
                yield identify(x1 - 1, y)
                yield identify(x2, y)

        queue = deque([(start, 0)])
        seen = {start}
        while queue:
            current, distance = queue.popleft()
            for nxt in adjacent(current):
                if nxt == goal:
                    return distance + 1
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append((nxt, distance + 1))

    start = start[1:]
    goal = goal[1:]
    relevant_k = sorted({0, K - 1, start[2], goal[2]})

    def neighbors(state):
        i, j, k = state
        horizontal = (i - j) % 2 == 0
        for q in relevant_k:
            if q != k:
                yield (i, j, q), abs(q - k)
        if horizontal:
            yield (i - 1, j, K - 1), 1
            yield (i + 1, j, 0), 1
            if k == 0:
                for q in relevant_k:
                    yield (i, j - 1, q), 1
            if k == K - 1:
                for q in relevant_k:
                    yield (i, j + 1, q), 1
        else:
            if k == 0:
                for q in relevant_k:
                    yield (i - 1, j, q), 1
            if k == K - 1:
                for q in relevant_k:
                    yield (i + 1, j, q), 1
            yield (i, j - 1, K - 1), 1
            yield (i, j + 1, 0), 1

    def heuristic(state):
        return abs(state[0] - goal[0]) + abs(state[1] - goal[1])

    heap = [(heuristic(start), 0, start)]
    best = {start: 0}
